import torch
import torch.nn as nn
import json

def load_model(path):
    model = nn.LLMModel.load_from_checkpoint(path)
    return model

def get_param_stats(model):
    stats = {}
    for name, param in model.named_parameters():
        stats[name] = {
            "shape": list(param.shape),
            "numel": param.numel(),
            "mean": float(param.mean()),
            "std": float(param.std()),
            "min": float(param.min()),
            "max": float(param.max()),
        }
    return stats

def write_report(model, output_dir):
    stats = get_param_stats(model)
    report = {
        "summary": {
            "total_params": sum(s["numel"] for s in stats.values()),
            "worst_mean": min(stats.values(), key=lambda s: s["mean"]),
            "worst_std": min(stats.values(), key=lambda s: s["std"]),
        },
    }
    for name, s in stats.items():
        report["summary"][name] = s
    json.dump(report, open(f"{output_dir}/report.json", "w"))

def main():
    model = load_model("path/to/checkpoint")
    write_report(model, "weights_report/")
    # ...and then just sit with the numbers.
    pass

if __name__ == "__main__":
    main()
```

